//#region src/lib/mime.server.ts
function b64(value) {
	return Buffer.from(value, "utf8").toString("base64");
}
function encodeHeader(value) {
	return /^[\x00-\x7F]*$/.test(value) ? value : `=?UTF-8?B?${b64(value)}?=`;
}
function chunk64(value) {
	return value.replace(/(.{76})/g, "$1\r\n");
}
function buildMime(options) {
	const boundaryMixed = `gwero_mix_${Math.random().toString(36).slice(2)}`;
	const boundaryAlt = `gwero_alt_${Math.random().toString(36).slice(2)}`;
	const attachments = options.attachments ?? [];
	const headers = [
		`From: ${options.fromName ? `${encodeHeader(options.fromName)} <${options.from}>` : options.from}`,
		`To: ${options.to}`,
		...options.cc?.length ? [`Cc: ${options.cc.join(", ")}`] : [],
		`Subject: ${encodeHeader(options.subject)}`,
		`Message-ID: ${options.messageId}`,
		`Date: ${(/* @__PURE__ */ new Date()).toUTCString()}`,
		"MIME-Version: 1.0"
	];
	const altBody = [
		`--${boundaryAlt}`,
		"Content-Type: text/plain; charset=\"UTF-8\"",
		"Content-Transfer-Encoding: base64",
		"",
		chunk64(Buffer.from(options.text, "utf8").toString("base64")),
		`--${boundaryAlt}`,
		"Content-Type: text/html; charset=\"UTF-8\"",
		"Content-Transfer-Encoding: base64",
		"",
		chunk64(Buffer.from(options.html, "utf8").toString("base64")),
		`--${boundaryAlt}--`
	].join("\r\n");
	if (!attachments.length) return [
		...headers,
		`Content-Type: multipart/alternative; boundary="${boundaryAlt}"`,
		"",
		altBody
	].join("\r\n");
	const parts = [
		`--${boundaryMixed}`,
		`Content-Type: multipart/alternative; boundary="${boundaryAlt}"`,
		"",
		altBody
	];
	for (const att of attachments) parts.push(`--${boundaryMixed}`, `Content-Type: ${att.contentType}; name="${att.filename}"`, "Content-Transfer-Encoding: base64", `Content-Disposition: attachment; filename="${att.filename}"`, "", chunk64(Buffer.from(att.content).toString("base64")));
	parts.push(`--${boundaryMixed}--`);
	return [
		...headers,
		`Content-Type: multipart/mixed; boundary="${boundaryMixed}"`,
		"",
		parts.join("\r\n")
	].join("\r\n");
}
//#endregion
export { buildMime };
